"""Mọi bảng (trừ pois) dùng một cột khóa chính `id bigint GENERATED BY DEFAULT AS IDENTITY`

Revision ID: 0004
Revises: 0003
Create Date: 2026-10-16

- Mã của batdongsan giữ nguyên giá trị nhưng không còn là khóa chính: `id` cũ của
  districts_old / wards_old / wards_new / streets_* đổi tên `source_id` (UNIQUE; với đường là
  UNIQUE theo cặp cùng khóa cha), `code` của provinces_* và `listing_id` của listings thêm UNIQUE.
- Mọi khóa ngoài chuyển sang bigint trỏ vào `id` mới (province_code -> province_id; ở hai bảng
  con của listings, listing_id text -> listing_pk). Dữ liệu được nối lại qua mã nguồn cũ.
- Hai bảng con của listings bỏ cột text listing_id: giữ lại sẽ là dữ liệu trùng phải tự đồng bộ.
- Hàm refresh_spatial_features() và refresh_listing_address_ids() viết lại theo cột mới.

Downgrade dựng lại khóa cũ từ mã nguồn nên dữ liệu về đúng như trước (giá trị `id` mới mất).
"""

import importlib

from alembic import op

revision = "0004"
down_revision = "0003"
branch_labels = None
depends_on = None

baseline = importlib.import_module("migrations.versions.0001_baseline")
school_patch = importlib.import_module("migrations.versions.0003_school_features_skip_universities")

# Bảng -> khóa chính cũ (đúng thứ tự trong 0001), để dựng lại khi downgrade
OLD_PRIMARY_KEYS = {
    "provinces_old": "code",
    "provinces_new": "code",
    "districts_old": "id",
    "wards_old": "id",
    "streets_old": "id, district_id",
    "wards_new": "id",
    "streets_new": "id, ward_id",
    "ward_mappings": "old_ward_id",
    "district_label": "model_version, label",
    "listings": "listing_id",
    "listing_embeddings": "listing_id",
    "listing_spatial_features": "listing_id",
}
# Bảng có `id` batdongsan -> đổi tên thành source_id
SOURCE_ID_TABLES = ["districts_old", "wards_old", "wards_new", "streets_old", "streets_new"]
# Cột mã UNIQUE giữ lại (bảng -> cột); streets_* UNIQUE theo cặp nên khai báo riêng ở dưới
UNIQUE_CODES = {
    "provinces_old": "code", "provinces_new": "code", "districts_old": "source_id",
    "wards_old": "source_id", "wards_new": "source_id", "listings": "listing_id",
}
# Bảng cha -> (cột mã nguồn dùng để nối dữ liệu cũ, kiểu cột khóa ngoài cũ); mặc định source_id
PARENT_CODES = {
    "provinces_old": ("code", "text"), "provinces_new": ("code", "text"),
    "listings": ("listing_id", "text"),
}
# (bảng, cột mới, cột cũ, bảng cha, ràng buộc phụ). Cột NOT NULL trừ các cột địa chỉ của listings.
FOREIGN_KEYS = [
    ("districts_old", "province_id", "province_code", "provinces_old", "index"),
    ("wards_old", "district_id", "district_id", "districts_old", "index"),
    ("streets_old", "district_id", "district_id", "districts_old", "index"),
    ("wards_new", "province_id", "province_code", "provinces_new", "index"),
    ("streets_new", "ward_id", "ward_id", "wards_new", "index"),
    ("ward_mappings", "old_ward_id", "old_ward_id", "wards_old", "unique"),
    ("ward_mappings", "new_ward_id", "new_ward_id", "wards_new", "index"),
    ("district_label", "district_id", "district_id", "districts_old", None),
    ("listings", "old_district_id", "old_district_id", "districts_old", "index"),
    ("listings", "old_ward_id", "old_ward_id", "wards_old", "index"),
    ("listings", "new_ward_id", "new_ward_id", "wards_new", "index"),
    ("listing_embeddings", "listing_pk", "listing_id", "listings", "unique"),
    ("listing_spatial_features", "listing_pk", "listing_id", "listings", "unique"),
]
CHILD_TABLES = ("listing_embeddings", "listing_spatial_features")
# Ràng buộc UNIQUE nhiều cột sau khi đổi: (bảng, tên, cột)
COMPOSITE_UNIQUES = [
    ("streets_old", "streets_old_source_id_district_id_key", "source_id, district_id"),
    ("streets_new", "streets_new_source_id_ward_id_key", "source_id, ward_id"),
    ("district_label", "district_label_model_version_label_key", "model_version, label"),
    ("district_label", "district_label_model_version_district_id_key",
     "model_version, district_id"),
]
FILTER_INDEX = "listings_filter_idx ON listings (property_type, old_district_id, price)"


def execute(*statements: str) -> None:
    """exec_driver_sql để dấu ':' và '%' trong thân hàm không bị coi là tham số."""
    for statement in statements:
        op.get_bind().exec_driver_sql(statement)


def fk_clause(table: str, column: str, parent: str, parent_key: str) -> str:
    cascade = " ON DELETE CASCADE" if table in CHILD_TABLES else ""
    return (f"ALTER TABLE {table} ADD CONSTRAINT {table}_{column}_fkey "
            f"FOREIGN KEY ({column}) REFERENCES {parent} ({parent_key}){cascade}")


def new_functions() -> tuple[str, str]:
    """Hàm của 0001 (+ sửa của 0003) với tên cột mới; assert để lệch bản gốc thì dừng ngay."""
    spatial = baseline.REFRESH_SPATIAL_FEATURES_SQL.replace(
        school_patch.SCHOOL, school_patch.GENERIC_SCHOOL)
    address = baseline.REFRESH_LISTING_ADDRESS_IDS_SQL
    spatial_edits = [
        ("WHERE l.listing_id = f.listing_id AND", "WHERE l.id = f.listing_pk AND"),
        ("AS f (\n        listing_id,", "AS f (\n        listing_pk,"),
        ("SELECT l.listing_id,\n           c.school_1km", "SELECT l.id,\n           c.school_1km"),
        ("ON CONFLICT (listing_id)", "ON CONFLICT (listing_pk)"),
    ]
    address_edits = [
        ("SELECT x.listing_id, od.id", "SELECT x.id AS listing_pk, od.id"),
        ("WHERE l.listing_id = m.listing_id", "WHERE l.id = m.listing_pk"),
        ("d.province_code = 'SG'",
         "d.province_id = (SELECT id FROM provinces_old WHERE code = 'SG')"),
        ("w.province_code = 'SG'",
         "w.province_id = (SELECT id FROM provinces_new WHERE code = 'SG')"),
    ]
    for old, new in spatial_edits:
        assert spatial.count(old) == 1, old
        spatial = spatial.replace(old, new)
    for old, new in address_edits:
        assert address.count(old) == 1, old
        address = address.replace(old, new)
    return spatial, address


def upgrade() -> None:
    for table, _, old, *_ in FOREIGN_KEYS:
        execute(f"ALTER TABLE {table} DROP CONSTRAINT {table}_{old}_fkey")
    for table in OLD_PRIMARY_KEYS:
        execute(f"ALTER TABLE {table} DROP CONSTRAINT {table}_pkey")
    for table in SOURCE_ID_TABLES:
        execute(f"ALTER TABLE {table} RENAME COLUMN id TO source_id")
    for table in OLD_PRIMARY_KEYS:
        execute(f"ALTER TABLE {table} ADD COLUMN id bigint GENERATED BY DEFAULT AS IDENTITY",
                f"ALTER TABLE {table} ADD CONSTRAINT {table}_pkey PRIMARY KEY (id)")
    for table, column in UNIQUE_CODES.items():
        execute(f"ALTER TABLE {table} ADD CONSTRAINT {table}_{column}_key UNIQUE ({column})")

    # Cột khóa ngoài: thêm cột tạm, nối qua mã nguồn cũ, bỏ cột cũ, đổi tên cột tạm
    for table, new, old, parent, extra in FOREIGN_KEYS:
        parent_key = PARENT_CODES.get(parent, ("source_id",))[0]
        execute(
            f"ALTER TABLE {table} ADD COLUMN {new}_tmp bigint",
            f"UPDATE {table} t SET {new}_tmp = p.id FROM {parent} p WHERE p.{parent_key} = t.{old}",
            f"ALTER TABLE {table} DROP COLUMN {old}",
            f"ALTER TABLE {table} RENAME COLUMN {new}_tmp TO {new}",
        )
        if table != "listings":
            execute(f"ALTER TABLE {table} ALTER COLUMN {new} SET NOT NULL")
        execute(fk_clause(table, new, parent, "id"))
        if extra == "index":
            execute(f"CREATE INDEX {table}_{new}_idx ON {table} ({new})")
        elif extra == "unique":
            execute(f"ALTER TABLE {table} ADD CONSTRAINT {table}_{new}_key UNIQUE ({new})")
    for table, name, columns in COMPOSITE_UNIQUES:
        execute(f"ALTER TABLE {table} ADD CONSTRAINT {name} UNIQUE ({columns})")
    execute(f"CREATE INDEX {FILTER_INDEX}")
    for sql in new_functions():
        execute(sql)


def downgrade() -> None:
    for table, new, *_ in FOREIGN_KEYS:
        execute(f"ALTER TABLE {table} DROP CONSTRAINT {table}_{new}_fkey")
    for table, name, _ in COMPOSITE_UNIQUES:
        execute(f"ALTER TABLE {table} DROP CONSTRAINT {name}")
    for table, new, old, parent, _ in FOREIGN_KEYS:
        parent_key, old_type = PARENT_CODES.get(parent, ("source_id", "integer"))
        execute(
            f"ALTER TABLE {table} ADD COLUMN {old}_tmp {old_type}",
            f"UPDATE {table} t SET {old}_tmp = p.{parent_key} FROM {parent} p WHERE p.id = t.{new}",
            f"ALTER TABLE {table} DROP COLUMN {new}",
            f"ALTER TABLE {table} RENAME COLUMN {old}_tmp TO {old}",
        )
        if table != "listings":
            execute(f"ALTER TABLE {table} ALTER COLUMN {old} SET NOT NULL")
    for table, column in UNIQUE_CODES.items():
        execute(f"ALTER TABLE {table} DROP CONSTRAINT {table}_{column}_key")
    for table, primary_key in OLD_PRIMARY_KEYS.items():
        execute(f"ALTER TABLE {table} DROP COLUMN id")
        if table in SOURCE_ID_TABLES:
            execute(f"ALTER TABLE {table} RENAME COLUMN source_id TO id")
        execute(f"ALTER TABLE {table} ADD CONSTRAINT {table}_pkey PRIMARY KEY ({primary_key})")
    execute("ALTER TABLE district_label ADD CONSTRAINT "
            "district_label_model_version_district_id_key UNIQUE (model_version, district_id)")
    for table, _, old, parent, extra in FOREIGN_KEYS:
        parent_key = PARENT_CODES.get(parent, ("id",))[0]  # source_id đã đổi lại thành id
        execute(fk_clause(table, old, parent, parent_key))
        if extra == "index":
            execute(f"CREATE INDEX {table}_{old}_idx ON {table} ({old})")
    execute(f"CREATE INDEX {FILTER_INDEX}")
    execute(school_patch.OLD_SQL.replace(school_patch.SCHOOL, school_patch.GENERIC_SCHOOL),
            baseline.REFRESH_LISTING_ADDRESS_IDS_SQL)
